<script setup lang="ts">import{reactive,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{api}from'../../api';const orderId=ref(''),submitting=ref(false),form=reactive({type:'quality',description:'商品存在质量问题，希望退款',images:['mock://quality-proof.jpg']});onLoad(q=>{orderId.value=String(q?.orderId||'')});async function submit(){if(form.description.length<5){uni.showToast({title:'请详细描述问题',icon:'none'});return}submitting.value=true;try{await api.createAfterSale(orderId.value,{...form});uni.showToast({title:'售后申请已通过',icon:'success'});setTimeout(()=>uni.redirectTo({url:'/pages/after-sales/index'}),600)}finally{submitting.value=false}}</script>
<template><view class="page"><view class="tip">MVP 使用自动审核，提交后将立即生成 Mock 退款。</view><view class="form card"><text class="label">问题类型</text><view class="types"><view v-for="item in [['quality','质量问题'],['missing','商品缺失'],['damaged','包装破损']]" :key="item[0]" class="type" :class="{'type--active':form.type===item[0]}" @tap="form.type=item[0]">{{item[1]}}</view></view><text class="label">问题描述</text><textarea v-model="form.description" maxlength="300" placeholder="请说明商品出现了什么问题"/><text class="label">问题凭证</text><view class="proof">Mock 图片凭证已添加</view></view><button class="primary-btn" :disabled="submitting" @tap="submit">{{submitting?'正在提交…':'提交售后申请'}}</button></view></template>
<style scoped lang="scss">@import '../../styles/theme.scss';.tip{background:#fff0ca;color:#604520;padding:22rpx;border-radius:22rpx;margin-bottom:22rpx}.form{padding:28rpx}.label{display:block;font-weight:900;margin:18rpx 0}.types{display:flex;gap:12rpx}.type{padding:16rpx 20rpx;border:2rpx solid $line;border-radius:20rpx;font-size:23rpx}.type--active{background:$ink;color:#fff}.form textarea{width:100%;height:220rpx;background:$paper;border-radius:22rpx;padding:20rpx;line-height:1.6}.proof{height:120rpx;border:3rpx dashed $line;border-radius:22rpx;display:flex;align-items:center;justify-content:center;color:$muted}.primary-btn{margin-top:30rpx}</style>
